function countPrefixed(words: string[], pref: string): number {
  const m = pref.length;
  let count = 0;
  for (const w of words) {
    if (w.length < m) continue;
    let i = 0;
    while (i < m && w[i] === pref[i]) i++;
    if (i === m) count++;
  }
  return count;
}

