class Solution:
    def countPrefixed(self, words: List[str], pref: str) -> int:
        m = len(pref)
        count = 0
        for w in words:
            if len(w) < m:
                continue
            i = 0
            while i < m and w[i] == pref[i]:
                i += 1
            if i == m:
                count += 1
        return count

